// src/domain/lumistry-occupations.ts
var OCCUPATION_VERSION = "jobs-20261013-1";
var domainCategories = { adult_industry: ["other"], agriculture_environment: ["other"], care_community: ["public service"], creative_media: ["artist"], education_culture: ["teacher"], healthcare: ["healthcare"], hospitality_food: ["hospitality"], industrial_utilities: ["tradesperson"], occasional_gigs: ["other"], office_finance_legal: ["finance"], performance_sports: ["other"], personal_services: ["other"], public_safety_government: ["public service"], retail_customer: ["retail"], science_engineering: ["researcher"], technology: ["technology"], trades_construction: ["tradesperson"], transport_logistics: ["other"] };
function metadata(row) {
  const r = row, id = r.id;
  const caps = new Set;
  const require2 = (test, cap) => {
    if (test)
      caps.add(cap);
  };
  require2(r.worldTags === "MCS", "electricity");
  require2(/software|online_|livestream|video_|virtual_streamer|influencer|podcast|social_media|community_moderator|thumbnail|platform|game_(artist|designer|localization|mod)|website|newsletter|app_based|network_|it_support/.test(id), "digital_networks");
  require2(/livestream|video_creator|virtual_streamer|podcaster|cam_performer/.test(id), "broadcast");
  require2(/electrician|electronics|lighting|sound_technician|cnc|refrigeration|solar_panel|wind_turbine|power_station|telecommunications/.test(id), "electricity");
  require2(/factory|production_line|food_packaging|industrial|cnc|chemical_plant|grain_storage|water_treatment|sewage_treatment/.test(id), "industrial");
  require2(/driver|van_|truck_|bus_driver|car_mechanic|vehicle_body|agricultural_equipment|food_truck/.test(id), "motor_transport");
  require2(/airport|flight_attendant|aircraft|commercial_pilot|air_traffic/.test(id), "aviation");
  require2(/railway|train_conductor/.test(id), "railways");
  require2(/supermarket|grocery_shelf/.test(id), "large_retail");
  require2(r.domain === "healthcare" || /veterinar/.test(id), "clinical_care");
  require2(/university|surgeon|general_practitioner|chemist|microbiologist|registered_dietitian/.test(id), "higher_education");
  require2(/ship_|harbour|marine_|commercial_fisher|commercial_diver|port_crane/.test(id), "marine");
  require2(/ski_instructor|snow_shovelling/.test(id), "snow");
  if (r.capability)
    caps.add(r.capability);
  let categories = [...domainCategories[r.domain] || ["other"]];
  if (/designer|stylist/.test(id))
    categories = ["designer"];
  if (/writer|copy_editor|reporter|subtitle_editor|transcriptionist|newsletter/.test(id))
    categories = ["writer"];
  if (/musician|singer|music_teacher|club_dj/.test(id))
    categories = ["musician"];
  if (/engineer|architect|quantity_surveyor/.test(id))
    categories = ["engineer"];
  if (/lawyer|paralegal|legal_secretary/.test(id))
    categories = ["law"];
  if (/receptionist|administrative_assistant|data_entry|records_clerk|purchasing_assistant|human_resources|recruitment/.test(id))
    categories = ["other"];
  if (/chef|cook|baker/.test(id))
    categories = ["chef", "hospitality"];
  if (/photographer|painter|illustrator|artist|animator|model|actor|costume|wig_maker|prop_maker/.test(id) && r.domain !== "adult_industry")
    categories = ["artist"];
  const advanced = /surgeon|general_practitioner|dentist$|veterinarian$|university_lecturer|harbour_pilot/.test(id);
  const qualified = /pharmacist$|physiotherapist|occupational_therapist|radiographer|optometrist|speech_language|registered_dietitian|engineer$|architect$|lawyer$|commercial_pilot|air_traffic_controller/.test(id);
  const privatePractice = /dentist$|general_practitioner|surgeon$|physiotherapist|occupational_therapist|optometrist|speech_language|registered_dietitian/.test(id);
  const institutional = r.use === "M" && !privatePractice && /healthcare|public_safety_government|industrial_utilities|transport_logistics/.test(r.domain);
  return { ...r, requiredCapabilities: [...caps], categories, minAge: advanced ? 27 : qualified ? 21 : 18, relationships: institutional ? ["employee"] : r.use === "G" ? ["contractor", "agency_worker"] : ["employee", "contractor", "independent_business_owner"], hours: r.use === "G" ? ["variable_hours", "project_based"] : institutional ? ["full_time", "part_time", "shift_based"] : ["full_time", "part_time", "variable_hours", "project_based"], places: /online|software|writer|editor|digital|remote|newsletter/.test(id) ? ["remote", "hybrid", "on_site"] : ["on_site"] };
}
var OCCUPATIONS = OCCUPATION_ROWS.map(metadata);
var OCCUPATION_BY_ID = new Map(OCCUPATIONS.map((r) => [r.id, r]));
