      const comment = walletText(input.text, 600), result = await this.generate(state, app, requestId, 'Continue this fictional stream. Return {"scene":"","viewers":50,"streamerReply":"","chat":[{"author":"","text":""}],"donations":[{"author":"","text":"","amount":5}]}. Do not speak for the user. Donations are fictional and only allowed for the user\u2019s own stream. At most 2 donations, at most 1000 each.', { stream, comment, donation }, context, user);
