  if (initial.pair.d.relationships.insights?.[id]?.assessmentReceipt === initial.receipt || !initial.anchors.length)
    return "This evidence has already been assessed. No request was made.";
  const frame = { profileId: id, revision: initial.revision, source: initial.evidence.at(-1).channel, key: "assessment:" + requestId, at, evidence: initial.evidence, anchors: initial.anchors, emotions: true, assessment: true };
  const result = await generate({ type: "quiet", messages: [{ role: "system", content: loveGuidance(state, frame) + `
Explicit assessment only: return {relationshipFeedback: feedback}. No dialogue, images or events.` }, { role: "user", content: JSON.stringify({ task: "relationship-assess", profileId: id }) }], parameters: { temperature: 0.2 } });
  current();
