function personaEnhancementRequest(evidence, currentDraft, worldFields) {
  const originalPersona = evidence.originalPersona;
  const reviewed = currentDraft ? Object.fromEntries(["alias", "age", "anonymous", "pronouns", "bio", "fields", "hiddenFields", "privateFields", "phoneProfile", "person"].filter((k) => currentDraft[k] !== undefined).map((k) => [k, structuredClone(currentDraft[k])])) : undefined;
  const seen = new Set;
  const canonical = (s) => s.replace(/\s+/g, " ").trim();
  const collect = (v) => {
    if (typeof v === "string" && canonical(v).length >= 40)
      seen.add(canonical(v));
    else if (Array.isArray(v))
      v.forEach(collect);
    else if (v && typeof v === "object")
      Object.values(v).forEach(collect);
  };
  collect(originalPersona);
  collect(reviewed);
  const unique = (v) => {
    if (typeof v === "string") {
      const key = canonical(v);
      if (!key)
        return;
      if (key.length < 40)
        return v;
      if (seen.has(key))
        return;
      seen.add(key);
      return v;
    }
    if (!v || typeof v !== "object")
      return;
    const entries = Object.entries(v).map(([k, x]) => [k, unique(x)]).filter(([, x]) => x !== undefined);
    return entries.length ? Object.fromEntries(entries) : undefined;
  };
  const p = evidence.pocketPersona || {};
  const pocketPersona = unique({ displayName: p.displayName, pronouns: p.pronouns, role: p.role, identityBrief: p.identityBrief, phoneProfile: p.phoneProfile });
  return { persona: { originalPersona, pocketPersona, sourceSelection: evidence.sourceSelection }, currentDraft: reviewed, hasSavedPhotoPlans: !!currentDraft?.photoPlan?.length, worldFields };
}
async function loadDatingPersonaEvidence(pocketPersona, personas, permitted, userId) {
  const check = () => {
    if (!permitted())
      throw new Error("Enable Personas permission so Lumistry can read your original Persona together with your Pocket Persona.");
  };
  check();
  const linkedId = pocketPersona.linkedPersonaId?.trim();
  const original = linkedId ? await personas.get(linkedId, userId) : await personas.getActive(userId);
  check();
  if (!original)
    throw new Error(linkedId ? "Your linked original Persona could not be read. Check the Persona link in Pocket settings." : "Select an active Persona in Lumiverse, then enhance again. Lumistry needs both the original Persona and Pocket Persona.");
  return {
    pocketPersona: structuredClone(pocketPersona),
    originalPersona: {
      id: original.id,
      name: original.name,
      title: original.title,
      description: original.description,
      pronouns: typeof original.metadata?.pronouns === "string" ? original.metadata.pronouns : "",
      role: typeof original.metadata?.role === "string" ? original.metadata.role : ""
    },
    sourceSelection: linkedId ? "linked" : "active"
  };
}

// src/domain/lumistry-development-contract.ts
function verifiedDatingEncounter(s, p) {
  const contact = s.contacts.find((c) => c.id === p.contactId), scene = s.sceneSnapshot;
  if (contact?.presence.inScene && scene && !scene.stale && scene.sourceMessageId && scene.actors.some((a) => a.contactId === p.contactId))
    return [`scene:${scene.sourceMessageId}:${scene.sourceRevision}`];
  const relay = (s.relays || []).find((r) => r.chatId === s.chatId && r.characterId === s.characterId && r.contactId === p.contactId && r.status === "consumed" && r.continuation.state === "completed" && r.consumedMessageId && r.actorState !== "arriving" && s.conversations.some((c) => c.id === r.conversationId && c.includesPocketPersona && c.participantContactIds.includes(p.contactId)));
  return relay ? [`relay:${relay.id}`, `message:${relay.consumedMessageId}`] : [];
}
function developmentTrigger(s, p, stage) {
  const d = datingFor(s), decision = d.decisions.find((x) => x.profileId === p.id);
  if (stage === "match")
    return decision?.status === "matched" ? { kind: "MUTUAL_MATCH", evidence: [`match:${decision.profileId}:${decision.conversationId}`] } : undefined;
  const encounter = verifiedDatingEncounter(s, p);
  if (encounter.length)
    return { kind: "ENCOUNTER_CONFIRMED", evidence: encounter };
  return decision?.exchanged ? { kind: "CONTACT_ONLY", evidence: d.relationships.events.filter((e) => e.profileId === p.id && e.kind === "exchange" && e.status === "confirmed").map((e) => `exchange:${e.id}`).concat(`exchange-confirmed:${p.id}:${decision.conversationId}`) } : undefined;
}
var modules = {
  MUTUAL_MATCH: [
    { key: "daily", label: "Unseen daily life", guidance: "Add one compatible ordinary detail. No mandatory project, crisis or major backstory." },
    { key: "voice", label: "Texting voice in practice", guidance: "A short new voice example, explicitly a sample rather than a committed message." },
    { key: "disclosure", label: "Trust and disclosure", guidance: "Individual reservations or pace; no promised attraction, intimacy, meeting or exchange." }
  ],
  CONTACT_ONLY: [
    { key: "knowledge", label: "Who knows what", guidance: "Knowledge from actual public material and exchanged words only; private work/employer details stay private unless disclosed." },
    { key: "channels", label: "Cross-channel behavior", guidance: "How the same individual uses dating and ordinary contact, without inventing a physical meeting or numeric reply timers." }
  ],
  ENCOUNTER_CONFIRMED: [
    { key: "knowledge", label: "Who knows what", guidance: "Separate actual observed facts and disclosures from own-private knowledge." },
    { key: "presence", label: "Physical presence", guidance: "Evidence-backed physical portrayal consistent with accepted anatomy. Compatible occasion clothing may reflect accepted style without rerolling it. Do not invent touching, attraction or further events." },
    { key: "initiative", label: "Independent initiative", guidance: "Compact performance guidance for choices and refusals; not a new event or fixed script." }
  ]
};
function pendingDevelopmentModules(p, t) {
  if (t.kind === "MUTUAL_MATCH" && p.development?.match && !p.development.units)
    return [];
  if (t.kind === "CONTACT_ONLY" && p.development?.portrayal && !p.development.units)
    return [];
  return modules[t.kind].filter((m) => !p.development?.units?.[`${t.kind}:${m.key}`] && (p.development?.unitAttempts?.[`${t.kind}:${m.key}`] || 0) < 2);
}
function developmentAuthority(module, newPerson = false) {
  if (module.key === "voice")
    return "diagnostic";
  if (["knowledge", "presence"].includes(module.key))
    return "witnessed";
  if (newPerson && ["daily", "disclosure"].includes(module.key))
    return "private-background";
  return "performance";
}
function developmentPrompt(fields, trigger, newPerson = false) {
  return `The verified ${trigger} evidence establishes eligibility, not that the other participant witnessed newly authored background. Respect each module\u2019s authority below. Preserve age, work, identity, commitments, orientation and all accepted facts. This response cannot commit events or disclose secrets to others. Ordinary contentment and little change are valid. No JSON or invented IDs. Return only these labeled answers, usually one short sentence each. Keep the whole record under 4200 characters.
` + fields.map((m) => `${m.label}: [${{ witnessed: "Extract only supplied witnessed facts; unknown stays unknown.", "private-background": "For this Lumistry-created person, author compatible low-stakes private background. It becomes own-private reality, not another participant\u2019s knowledge or a witnessed event.", performance: "Conditional performance guidance grounded in the accepted person; no new biography or event.", diagnostic: "Diagnostic voice sample only; never a sent message, disclosure or event." }[developmentAuthority(m, newPerson)]} ${m.guidance}]`).join(`
`);
}
function parseDevelopmentModules(text, requested) {
  const result = new Map;
  let active, buffer = [];
  const flush = () => {
    if (active && buffer.join(`
`).trim()) {
      if (result.has(active.key))
        throw new Error("Repeated conflicting development module");
      result.set(active.key, buffer.join(`
`).trim());
    }
  };
  for (const line of text.split(/\r?\n/)) {
    const label = line.match(/^\s*(?:[-*]\s+)?(?:\*\*)?([^:\n]{1,100}?)(?:\*\*)?\s*:\s*(?:\*\*)?\s*(.*)$/);
    if (label) {
      flush();
      active = requested.find((m) => m.label.toLowerCase() === label[1].trim().toLowerCase());
      buffer = active ? [label[2]] : [];
    } else if (active)
      buffer.push(line);
  }
  flush();
  return requested.flatMap((module) => result.has(module.key) ? [{ module, text: result.get(module.key) }] : []);
}

