        return;
      job.controller.signal.throwIfAborted();
      const guestCards = app !== "discord" && this.host.listGuestCards ? socialGuestCards(await this.host.listGuestCards(state, app, owner, userId), state, owner) : [];
      job.controller.signal.throwIfAborted();
